<?php
require_once dirname(__DIR__) . '/app/init.php';
$customer = require_customer(); $pending = $_SESSION['_pending_checkout'] ?? null;
if (!$pending || ($pending['customer_id'] ?? 0) !== (int) $customer['id'] || ($pending['cart'] ?? []) !== get_cart() || ($pending['created_at'] ?? 0) < time() - 900) { unset($_SESSION['_pending_checkout']); flash('info', 'Please review your checkout details before demo payment.'); redirect('/checkout.php'); }
$summary = cart_summary(db()); $details = $pending['details'];
foreach ($summary['items'] as $item) { if (!isset($pending['expected_prices'][$item['id']]) || $pending['expected_prices'][$item['id']] !== $item['price'] || !(int) $item['is_active'] || $item['quantity'] > $item['stock_quantity']) { unset($_SESSION['_pending_checkout']); flash('info', 'An arrangement changed. Review your bag and details again before payment.'); redirect('/cart.php'); } }
$fee = app_config()[$details['fulfillment_method'] === 'delivery' ? 'delivery_fee' : 'pickup_fee'];
if ($fee !== ($details['expected_fee'] ?? null)) { unset($_SESSION['_pending_checkout']); flash('info', 'The fulfillment fee changed. Please review checkout again.'); redirect('/checkout.php'); }
$pageTitle = 'Review & demo payment'; require dirname(__DIR__) . '/templates/header.php';
?>
<div class="container"><section class="payment-panel"><?php $checkoutStep = 'payment'; require dirname(__DIR__) . '/templates/checkout_steps.php'; ?><span class="demo-label">SIMULATED PAYMENT · SCHOOL DEMO</span><h1>Ready to make<br>someone's day?</h1><p class="muted">Review your flowers and details below. Completing this demo records a simulated payment. No money is charged.</p><div class="review-list"><?php foreach ($summary['items'] as $item): ?><div class="review-item"><span><?= e($item['name']) ?> × <?= e($item['quantity']) ?></span><span><?= e(format_money($item['line_total'])) ?></span></div><?php endforeach; ?></div><div class="review-details"><div><h2><?= $details['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Store pickup' ?> · <?= e($details['scheduled_date']) ?></h2><?php if ($details['fulfillment_method'] === 'delivery'): ?><p><?= e($details['recipient_name']) ?><br><?= e($details['phone']) ?><br><?= nl2br(e($details['address'])) ?></p><?php else: ?><p>Your arrangement will be prepared for store pickup on your selected date.</p><?php endif; ?></div><div><h2>Gift message</h2><p><?= $details['gift_message'] !== '' ? nl2br(e($details['gift_message'])) : 'No gift message added.' ?></p></div></div><div class="summary-row"><span>Flowers</span><span><?= e(format_money($summary['subtotal'])) ?></span></div><div class="summary-row"><span><?= $details['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Pickup' ?> fee</span><span><?= e(format_money($fee)) ?></span></div><div class="summary-row summary-total"><span>Demo payment total</span><strong><?= e(format_money($summary['subtotal'] + money_to_minor($fee))) ?></strong></div><div class="payment-actions"><form action="<?= e(url('/actions/checkout.php')) ?>" method="post" data-submitting-label="Recording demo payment..."><?= csrf_field() ?><input type="hidden" name="action" value="pay"><input type="hidden" name="checkout_key" value="<?= e($pending['key']) ?>"><button class="button" type="submit">Complete demo payment ↗</button></form><a class="text-link" href="<?= e(url('/checkout.php')) ?>">Edit checkout details</a></div><p class="field-help">No card or banking details are needed. Your review expires after 15 minutes.</p></section></div><?php require dirname(__DIR__) . '/templates/footer.php'; ?>
